{
  "book_code": "4BAR",
  "verses": [
    {
      "chapter": 7,
      "text_ar": "فقال النسر: \"أقول لك يا إرميا: تعال، احلل هذه الرسالة واقرأها على الشعب\". فحل الرسالة وقرأها على الشعب.",
      "verse": 21
    },
    {
      "chapter": 7,
      "text_ar": "ولما سمعها الشعب، بكوا ووضعوا تراباً على رؤوسهم، وقالوا لإرميا: \"خلصنا وأخبرنا ماذا نعمل لكي ندخل مدينتنا مرة أخرى\".",
      "verse": 22
    },
    {
      "chapter": 7,
      "text_ar": "فأجاب إرميا وقال لهم: \"افعلوا كل ما سمعتموه من الرسالة، والرب سيقودنا إلى مدينتنا\".",
      "verse": 23
    },
    {
      "chapter": 7,
      "text_ar": "وكتب إرميا رسالة إلى باروخ قائلاً: \"يا ابني الحبيب، صلِ باجتهاد وتضرع إلى الله لأجلنا، لكي يهدي طريقنا حتى نخرج من ولاية هذا الملك فاقد الناموس.",
      "verse": 24
    },
    {
      "chapter": 7,
      "text_ar": "لأنك وُجدت باراً أمام الله، ولم يدعك تأتي إلى هنا، لكي لا ترى الضيق الذي حل بالشعب على أيدي البابليين.",
      "verse": 25
    }
  ]
}
